def main():
    out, vals, table = [HEADER], ["\nend Twins\n\n/-! ## The values, at `HotSizing.publicConst 64` -/\n"], []
    for rec, (pr, p, cof) in RECORDS.items():
        for cast, h in CASTS.items():
